{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms, round(min(duration)/1e6,1) min_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name='RouteController.queryAll' GROUP BY 1,2",
          "claim": "In the abnormal window every RouteController.queryAll span in ts-route-service takes about 1,426 ms, with a minimum of about 1,426 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM normal_traces WHERE service_name='ts-route-service' AND span_name='RouteController.queryAll' GROUP BY 1",
          "claim": "In the normal period the same method ran in about 4 ms at p50 across 726 spans, so the slowdown is new."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.5)/1e6,2) p50_ms, round(max(duration)/1e6,2) max_ms FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name IN ('RouteRepository.findAll','SELECT route.entity.Route','Session.find route.entity.Route','SELECT route_stations','GET /api/v1/routeservice/routes/{routeId}','RouteController.queryById') GROUP BY 1,2",
          "claim": "Database child spans and other route endpoints stay at about 1 ms, so the extra time sits inside the queryAll method itself."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-route-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE span_name='GET /api/v1/routeservice/routes' AND attr_span_kind='Server' GROUP BY 1,2,3",
          "claim": "ts-ui-dashboard's GET /api/v1/routeservice/routes server spans take about 1,428 ms at p50, against about 5.5 ms in the normal period, because they wait on route-service."
        }
      ]
    }
  ]
}
